362: static int check_image_header(const char *buf)
363: {
364:     if (!strncmp(buf, "\x89\x50\x4E\x47\x0D\x0A\x1A\x0A", 8))
365:         return 1;               /* PNG */
366:     else if (!strncmp(buf, "\xFF\xD8\xFF\xE0", 4) ||
367:              !strncmp(buf, "\xFF\xD8\xFF\xE1", 4))
368:         return 1;               /* JPEG */
369:     else if (!strncmp(buf, "GIF87a", 6) || !strncmp(buf, "GIF89a", 6))
370:         return 1;               /* GIF */
371:     else
372:         return 0;
373: }
