375: static int *mkChanMap(int channels, int center, int lf)
376: {
377:     int *map;
378:     int inpos;
379:     int outpos;
380: 
381:     if (!center && !lf)
382:         return NULL;
383: 
384:     if (channels < 3)
385:         return NULL;
386: 
387:     if (lf > 0)
388:         lf--;
389:     else
390:         lf = channels - 1;      // default AAC position
391: 
392:     if (center > 0)
393:         center--;
394:     else
395:         center = 0;             // default AAC position
396: 
397:     map = malloc(channels * sizeof(map[0]));
398:     if (!map) return NULL;
399:     memset(map, 0, channels * sizeof(map[0]));
400: 
401:     outpos = 0;
402:     if ((center >= 0) && (center < channels))
403:         map[outpos++] = center;
404: 
405:     inpos = 0;
406:     for (; outpos < (channels - 1) && inpos < channels; inpos++)
407:     {
408:         if (inpos == center)
409:             continue;
410:         if (inpos == lf)
411:             continue;
412: 
413:         map[outpos++] = inpos;
414:     }
415:     if (outpos < channels)
416:     {
417:         if ((lf >= 0) && (lf < channels))
418:             map[outpos] = lf;
419:         else if (inpos < channels)
420:             map[outpos] = inpos;
421:     }
422: 
423:     return map;
424: }
