773:                 break;
774:             }
775:         case SHORTCTL_FLAG:
776:             shortctl = atoi(optarg);
777:             break;
778:         case MPEGVERS_FLAG:
779:             mpegVersion = atoi(optarg);
780:             switch (mpegVersion)
781:             {
782:             case 2:
783:                 mpegVersion = MPEG2;
784:                 break;
785:             case 4:
786:                 mpegVersion = MPEG4;
