824: 
825:     /* check that we have at least one non-option arguments */
826:     if (!dieMessage && (argc - optind) > 1 && aacFileNameGiven)
827:         dieMessage =
828:             "Cannot encode several input files to one output file.\n";
829: 
830:     if (argc - optind < 1 || dieMessage)
831:     {
832:         fprintf(stderr, dieMessage, progName, progName, progName, progName);
833:         return 1;
834:     }
835: 
836:     while (argc - optind > 0)
837:     {
838:         /* get the input file name */
839:         audioFileName = argv[optind++];
840:     }
841: 
842:     /* generate the output file name, if necessary */
843:     if (!aacFileNameGiven)
844:     {
845:         char *t = strrchr(audioFileName, '.');
846:         int l = t ? strlen(audioFileName) - strlen(t) : strlen(audioFileName);
847: 
848:         aacFileExt = container == MP4_CONTAINER ? ".m4a" : ".aac";
849: 
850:         aacFileName = malloc(l + 1 + 4);
851:         if (!aacFileName)
852:         {
853:             fprintf(stderr, "out of memory\n");
854:             return 1;
855:         }
856:         memcpy(aacFileName, audioFileName, l);
857:         memcpy(aacFileName + l, aacFileExt, 4);
858:         aacFileName[l + 4] = '\0';
859:     }
860:     else
861:     {
862:         aacFileExt = strrchr(aacFileName, '.');
863: 
864:         if (aacFileExt
865:             && (!strcmp(".m4a", aacFileExt) || !strcmp(".m4b", aacFileExt)
866:                 || !strcmp(".mp4", aacFileExt)))
867:             container = MP4_CONTAINER;
868:     }
869: 
870:     /* open the audio input file */
871:     if (rawChans > 0)           // use raw input
872:     {
873:         infile = wav_open_read(audioFileName, 1);
874:         if (infile)
875:         {
876:             infile->bigendian = rawEndian;
877:             infile->channels = rawChans;
878:             infile->samplebytes = rawBits / 8;
879:             infile->samplerate = rawRate;
880:             infile->samples /= (infile->channels * infile->samplebytes);
881:         }
882:     }
883:     else                        // header input
884:         infile = wav_open_read(audioFileName, 0);
885: 
886:     if (infile == NULL)
887:     {
888:         fprintf(stderr, "Couldn't open input file %s\n", audioFileName);
889:         return 1;
890:     }
891: 
892:     /* open the encoder library */
893:     hEncoder = faacEncOpen(infile->samplerate, infile->channels,
894:                            &samplesInput, &maxBytesOutput);
895: 
896:     if (hEncoder == NULL)
897:     {
898:         fprintf(stderr, "Couldn't open encoder instance for input file %s\n",
899:                 audioFileName);
900:         wav_close(infile);
901:         return 1;
902:     }
903: 
904:     if (container != MP4_CONTAINER && (ntracks || trackno || artist ||
905:                                        artistsort || title ||
906:                                        album || albumartist ||
907:                                        albumartistsort ||
908:                                        albumsort || year || artData ||
909:                                        genre || comment || discno || ndiscs ||
910:                                        composer || composersort ||
911:                                        compilation))
912:     {
913:         fprintf(stderr, "Metadata requires MP4 output!\n");
914:         return 1;
915:     }
916: 
917:     if (container == MP4_CONTAINER)
918:     {
919:         mpegVersion = MPEG4;
920:         stream = RAW_STREAM;
921:     }
922: 
923:     frameSize = samplesInput / infile->channels;
924:     delay_samples = frameSize;  // encoder delay 1024 samples
925:     pcmbuf = (float *) malloc(samplesInput * sizeof(float));
926:     bitbuf = (unsigned char *) malloc(maxBytesOutput * sizeof(unsigned char));
927:     if (!pcmbuf || !bitbuf)
928:     {
929:         fprintf(stderr, "out of memory\n");
930:         return 1;
931:     }
932:     chanmap = mkChanMap(infile->channels, chanC, chanLF);
933:     if (chanmap)
934:     {
935:         fprintf(stderr, "Remapping input channels: Center=%d, LFE=%d\n",
936:                 chanC, chanLF);
937:     }
938: 
939:     if (cutOff <= 0)
940:     {
941:         if (cutOff < 0)         // default
942:             cutOff = 0;
943:         else                    // disabled
944:             cutOff = infile->samplerate / 2;
945:     }
946:     if (cutOff > (infile->samplerate / 2))
947:         cutOff = infile->samplerate / 2;
948: 
949:     /* put the options in the configuration struct */
950:     myFormat = faacEncGetCurrentConfiguration(hEncoder);
951:     myFormat->aacObjectType = objectType;
952:     myFormat->mpegVersion = mpegVersion;
953:     myFormat->useTns = useTns;
954:     switch (shortctl)
955:     {
956:     case SHORTCTL_NOSHORT:
957:         fprintf(stderr, "disabling short blocks\n");
958:         myFormat->shortctl = shortctl;
959:         break;
960:     case SHORTCTL_NOLONG:
961:         fprintf(stderr, "disabling long blocks\n");
962:         myFormat->shortctl = shortctl;
963:         break;
964:     }
965:     if (infile->channels >= 6)
966:         myFormat->useLfe = 1;
967:     if (jointmode >= 0)
968:         myFormat->jointmode = jointmode;
969: 
970:     if (pnslevel > 0 && mpegVersion == MPEG2)
971:     {
972:         fprintf(stderr, "PNS not allowed in MPEG-2 mode, disabling PNS\n");
973:         pnslevel = 0;
974:     }
975: 
976:     if (pnslevel >= 0)
977:         myFormat->pnslevel = pnslevel;
978:     if (quantqual > 0)
979:     {
980:         myFormat->quantqual = quantqual;
981:         myFormat->bitRate = 0;
982:     }
983:     if (bitRate)
984:         myFormat->bitRate = bitRate / infile->channels;
985:     myFormat->bandWidth = cutOff;
986:     myFormat->outputFormat = stream;
987:     myFormat->inputFormat = FAAC_INPUT_FLOAT;
988:     if (!faacEncSetConfiguration(hEncoder, myFormat))
989:     {
990:         fprintf(stderr, "Unsupported output format!\n");
991:         return 1;
992:     }
993: 
994:     /* initialize MP4 creation */
995:     if (container == MP4_CONTAINER)
996:     {
997:         if (!strcmp(aacFileName, "-"))
998:         {
999:             fprintf(stderr, "cannot encode MP4 to stdout\n");
1000:             return 1;
1001:         }
1002: 
1003:         if (mp4_open(aacFileName, overwrite))
1004:         {
1005:             fprintf(stderr, "Couldn't create output file %s\n", aacFileName);
1006:             return 1;
1007:         }
1008: 
1009:         mp4_set_format(infile->samplerate, infile->channels, infile->samplebytes * 8);
1010:     }
