119: static void seekcur(FILE *f, int ofs)
120: {
121:     if (ofs < 0)
122:         return;
123: 
124:     if (fseek(f, ofs, SEEK_CUR) != 0)
125:     {
126:         /* fseek fails on non-seekable streams (stdin/pipes); fall back to
127:            reading and discarding bytes one at a time */
128:         while (ofs--)
129:         {
130:             if (fgetc(f) == EOF)
131:                 break;
132:         }
133:     }
134: }
