136: static int seekchunk(FILE *f, riffsub_t *riffsub, char *name)
137: {
138:  int skipped;
139: 
140:  for(skipped = 0; skipped < 10; skipped++)
141:  {
142:    if (fread(riffsub, 1, sizeof(*riffsub), f) != sizeof(*riffsub))
143:      return 0;
144: 
145:    riffsub->len = UINT32(riffsub->len);
146:    if (riffsub->len & 1)
147:      riffsub->len++;
148: 
149:    if (!memcmp(&(riffsub->label), name, 4))
150:      return 1;
151: 
152:    seekcur(f, riffsub->len);
153:  }
154: 
155:  return 0;
156: }
