158: pcmfile_t *wav_open_read(const char *name, int rawinput)
159: {
160:   FILE *wave_f;
161:   riff_t riff;
162:   riffsub_t riffsub = {0};
163:   struct WAVEFORMATEXTENSIBLE wave;
164:   char *riffl = "RIFF";
165:   char *wavel = "WAVE";
166:   char *fmtl = "fmt ";
167:   char *datal = "data";
168:   int fmtsize;
169:   pcmfile_t *sndf;
170:   int dostdin = 0;
171: 
172:   if (!strcmp(name, "-"))
173:   {
174: #ifdef _WIN32
175:     _setmode(_fileno(stdin), O_BINARY);
176: #endif
177:     wave_f = stdin;
178:     dostdin = 1;
179:   }
180:   else if (!(wave_f = fopen(name, "rb")))
181:   {
182:     perror(name);
183:     return NULL;
184:   }
185: 
186:   if (!rawinput) // header input
187:   {
188:     if (fread(&riff, 1, sizeof(riff), wave_f) != sizeof(riff))
189:       return NULL;
190:     if (memcmp(&(riff.label), riffl, 4))
191:       return NULL;
192:     if (memcmp(&(riff.chunk_type), wavel, 4))
193:       return NULL;
194: 
195:     if (!seekchunk(wave_f, &riffsub, fmtl))
196:       return NULL;
197: 
198:     if (memcmp(&(riffsub.label), fmtl, 4))
199:         return NULL;
200:     memset(&wave, 0, sizeof(wave));
201: 
202:     fmtsize = (riffsub.len < sizeof(wave)) ? riffsub.len : sizeof(wave);
203:     // check if format is at least 16 bytes long
204:     if (fmtsize < 16)
205: 	return NULL;
206: 
207:    if (fread(&wave, 1, fmtsize, wave_f) != (size_t)fmtsize)
208:         return NULL;
209: 
210:     seekcur(wave_f, riffsub.len - fmtsize);
211: 
212:     if (!seekchunk(wave_f, &riffsub, datal))
213:       return NULL;
214: 
215:     if (UINT16(wave.Format.wFormatTag) != WAVE_FORMAT_PCM && UINT16(wave.Format.wFormatTag) != WAVE_FORMAT_FLOAT)
216:     {
217:       if (UINT16(wave.Format.wFormatTag) == WAVE_FORMAT_EXTENSIBLE)
218:       {
219:         if (UINT16(wave.Format.cbSize) < 22) // struct too small
220:           return NULL;
221:         if (memcmp(wave.SubFormat, waveformat_pcm_guid, 16))
222:         {
223:           waveformat_pcm_guid[0] = WAVE_FORMAT_FLOAT;
224:           if (memcmp(wave.SubFormat, waveformat_pcm_guid, 16))
225:           {          
226:             unsuperr(name);
227:             return NULL;
228:           }
229:         }
230:       }
231:       else
232:       {
233:         unsuperr(name);
234:         return NULL;
235:       }
236:     }
237:   }
238: 
239:   sndf = (pcmfile_t*)malloc(sizeof(*sndf));
240:   if (!sndf)
241:   {
242:       if (wave_f != stdin) fclose(wave_f);
243:       return NULL;
244:   }
245:   memset(sndf, 0, sizeof(*sndf));
246:   sndf->f = wave_f;
247: 
248:   if (UINT16(wave.Format.wFormatTag) == WAVE_FORMAT_FLOAT) {
249:     sndf->isfloat = 1;
250:   } else {
251:     sndf->isfloat = (wave.SubFormat[0] == WAVE_FORMAT_FLOAT);
252:   }
253:   if (rawinput)
254:   {
255:     sndf->bigendian = 1;
256:     if (dostdin)
257:       sndf->samples = 0;
258:     else
259:     {
260:       fseek(sndf->f, 0 , SEEK_END);
261:       sndf->samples = ftell(sndf->f);
262:       rewind(sndf->f);
263:     }
264:   }
265:   else
266:   {
267:     sndf->bigendian = 0;
268:     sndf->channels = UINT16(wave.Format.nChannels);
269:     sndf->samplebytes = UINT16(wave.Format.wBitsPerSample) / 8;
270:     sndf->samplerate = UINT32(wave.Format.nSamplesPerSec);
271: 
272:     /* channel/sample-width bounds guard against a corrupt header (e.g. a
273:        bogus huge channel count) driving an oversized allocation downstream */
274:     if (sndf->channels < 1 || sndf->channels > 64 ||
275:         sndf->samplebytes < 1 || sndf->samplebytes > 4)
276:     {
277:       if (wave_f != stdin) fclose(wave_f);
278:       free(sndf);
279:       return NULL;
280:     }
281: 
282:     sndf->samples = riffsub.len / (sndf->samplebytes * sndf->channels);
283:   }
284: 
285: #ifdef WORDS_BIGENDIAN
286:   sndf->swap = !sndf->bigendian;
287: #else
288:   sndf->swap = sndf->bigendian;
289: #endif
290: 
291:   return sndf;
292: }
