295: static void chan_remap(int32_t *buf, int channels, int blocks, int *map)
296: {
297:   int i;
298:   int32_t *tmp = (int32_t*)malloc(channels * sizeof(int32_t));
299: 
300:   if (!tmp) return;
301: 
302:   for (i = 0; i < blocks; i++)
303:   {
304:     int chn;
305: 
306:     memcpy(tmp, buf + i * channels, sizeof(int32_t) * channels);
307: 
308:     for (chn = 0; chn < channels; chn++)
309:       buf[i * channels + chn] = tmp[map[chn]];
310:   }
311:   free(tmp);
312: }
