314: size_t wav_read_float32(pcmfile_t *sndf, float *buf, size_t num, int *map)
315: {
316:   size_t cnt;
317:   size_t isize;
318:   char *bufi;
319: 
320:   if ((sndf->samplebytes > 4) || (sndf->samplebytes < 1))
321:     return 0;
322: 
323:   isize = num * sndf->samplebytes;
324:   bufi = (char*)(buf + num);
325:   bufi -= isize;
326:   isize = fread(bufi, 1, isize, sndf->f);
327:   isize /= sndf->samplebytes;
328: 
329:   // perform in-place conversion
330:   cnt = (num < isize) ? num : isize;
331: 
332:   if (sndf->isfloat)
333:   {
334:       if (sndf->samplebytes == 4)
335:       {
336:           for (size_t i = 0; i < cnt; i++)
337:               buf[i] *= 32768.0f;
338:       }
339:       else
340:       {
341:           return 0;
342:       }
343:   }
344:   else
345:   {
346:       switch (sndf->samplebytes)
347:       {
348:       case 1:
349:           {
350:               uint8_t *in = (uint8_t*)bufi;
351:               for (size_t i = 0; i < cnt; i++)
352:                   buf[i] = ((float)in[i] - 128.0f) * 256.0f;
353:           }
354:           break;
355:       case 2:
356:           {
357:               int16_t *in = (int16_t*)bufi;
358:               int swap = sndf->swap;
359:               if (swap)
360:               {
361:                   for (size_t i = 0; i < cnt; i++)
362:                       buf[i] = (float)SWAP16(in[i]);
363:               }
364:               else
365:               {
366:                   for (size_t i = 0; i < cnt; i++)
367:                       buf[i] = (float)in[i];
368:               }
369:           }
370:           break;
371:       case 3:
372:           {
373:               uint8_t *in = (uint8_t*)bufi;
374:               if (!sndf->bigendian)
375:               {
376:                   for (size_t i = 0; i < cnt; i++)
377:                   {
378:                       int s = in[3*i] | (in[3*i+1] << 8) | (in[3*i+2] << 16);
379:                       if (s & 0x800000) s |= 0xff000000;
380:                       buf[i] = (float)s / 256.0f;
381:                   }
382:               }
383:               else
384:               {
385:                   for (size_t i = 0; i < cnt; i++)
386:                   {
387:                       int s = (in[3*i] << 16) | (in[3*i+1] << 8) | in[3*i+2];
388:                       if (s & 0x800000) s |= 0xff000000;
389:                       buf[i] = (float)s / 256.0f;
390:                   }
391:               }
392:           }
393:         break;
394:       case 4:
395:           {
396:               int32_t *in = (int32_t*)bufi;
397:               int swap = sndf->swap;
398:               if (swap)
399:               {
400:                   for (size_t i = 0; i < cnt; i++)
401:                       buf[i] = (float)SWAP32(in[i]) / 65536.0f;
402:               }
403:               else
404:               {
405:                   for (size_t i = 0; i < cnt; i++)
406:                       buf[i] = (float)in[i] / 65536.0f;
407:               }
408:           }
409:           break;
410:       default:
411:           return 0;
412:       }
413:   }
414: 
415:   if (map)
416:     chan_remap((int32_t *)buf, sndf->channels, cnt / sndf->channels, map);
417: 
418:   return cnt;
419: }
