142:    instead of an lseek round trip. mdat audio bytes stream straight to
143:    g_mp4.fout instead, since they arrive incrementally during encoding
144:    and can be far larger than is worth buffering. */
145: static uint8_t *g_membuf = NULL;
146: static size_t g_mempos = 0;
147: static size_t g_memcap = 0;
148: /* Set whenever mem_write() can't grow g_membuf to fit a write and drops
149:    it instead; checked by mp4_finish() so a truncated moov atom is never
150:    mistaken for a successfully written one. */
151: static int g_mem_error = 0;
152: 
153: static inline void mem_write(const void *data, size_t size) {
154:     if (g_membuf) {
155:         if (g_mempos + size > g_memcap) {
156:             size_t new_cap = g_memcap ? g_memcap * 2 : 1024;
157:             /* cap growth so a bogus/huge write request can't spin the
158:                doubling loop forever or overflow new_cap */
159:             while (g_mempos + size > new_cap && new_cap < (1UL << 31)) new_cap *= 2;
160:             if (g_mempos + size > new_cap) { g_mem_error = 1; return; }
161:             void *tmp = realloc(g_membuf, new_cap);
162:             if (!tmp) {
163:                 free(g_membuf);
164:                 g_membuf = NULL;
165:                 g_mem_error = 1;
166:                 return;
167:             }
168:             g_membuf = (uint8_t *)tmp;
169:             g_memcap = new_cap;
170:         }
171:         memcpy(g_membuf + g_mempos, data, size);
172:         g_mempos += size;
173:     } else if (g_mp4.fout && !g_mem_error) {
174:         if (fwrite(data, 1, size, g_mp4.fout) != size)
175:             g_mem_error = 1;
176:     }
177: }
178: 
179: 
180: static inline void put_u32(uint32_t val) {
181: #ifndef WORDS_BIGENDIAN
182:     val = BSWAP32(val);
183: #endif
184:     if (g_membuf && g_mempos + 4 <= g_memcap) {
185:         memcpy(g_membuf + g_mempos, &val, 4);
186:         g_mempos += 4;
187:     } else {
188:         mem_write(&val, 4);
189:     }
190: }
191: 
192: static inline void put_u16(uint16_t val) {
193: #ifndef WORDS_BIGENDIAN
194:     val = BSWAP16(val);
195: #endif
196:     if (g_membuf && g_mempos + 2 <= g_memcap) {
197:         memcpy(g_membuf + g_mempos, &val, 2);
198:         g_mempos += 2;
199:     } else {
200:         mem_write(&val, 2);
201:     }
202: }
203: 
204: static inline void put_u8(uint8_t val) { mem_write(&val, 1); }
205: 
206: static inline void put_data(const void *data, size_t size) { mem_write(data, size); }
207: 
208: /* An atom's size field comes before its contents but isn't known until
209:    the contents (and any nested atoms) are written, so reserve it as 0
210:    here and let end_atom() backpatch the real value once it's known. */
211: static inline long start_atom(const char *name) {
212:     long pos = g_membuf ? (long)g_mempos : (g_mp4.fout ? ftell(g_mp4.fout) : 0);
213:     put_u32(0);
214:     put_data(name, 4);
215:     return pos;
216: }
217: 
218: static inline void end_atom(long pos) {
219:     if (g_membuf) {
220:         uint32_t size = (uint32_t)(g_mempos - pos);
221: #ifndef WORDS_BIGENDIAN
222:         size = BSWAP32(size);
223: #endif
224:         memcpy(g_membuf + pos, &size, 4);
225:     } else if (g_mp4.fout) {
226:         long curr = ftell(g_mp4.fout);
227:         fseek(g_mp4.fout, pos, SEEK_SET);
228:         put_u32((uint32_t)(curr - pos));
229:         fseek(g_mp4.fout, curr, SEEK_SET);
230:     }
231: }
