240: /* creation/modification time is informational only; the spec (14496-12) never
241:  * requires a real clock. Emit 0 ("unknown") by default so encodes are
242:  * byte-reproducible, matching common muxer practice. */
243: static uint32_t get_mp4_time(void) {
244:     return g_mp4.creation_time;
245: }
246: 
247: /* MPEG-4 descriptor sizes are a base-128 varint with a continuation bit,
248:    but always emitted here as the full 4-byte form (continuation bit set
249:    on all but the last byte) since some parsers assume that fixed width
250:    rather than the shorter encodings the spec also permits. */
251: static void put_descriptor(uint8_t tag, uint32_t size) {
252:     uint8_t buf[5];
253:     buf[0] = tag;
254:     buf[1] = ((size >> 21) & 0x7f) | 0x80;
255:     buf[2] = ((size >> 14) & 0x7f) | 0x80;
256:     buf[3] = ((size >> 7) & 0x7f) | 0x80;
257:     buf[4] = (size & 0x7f);
258:     mem_write(buf, 5);
259: }
260: 
261: /* Only resets per-output-file write state (frame table, mdat bookkeeping,
262:    bitrate accumulators). Tag/format config set by the caller, which may
263:    happen before or after mp4_open() depending on the option, is left
264:    untouched. */
265: static void reset_write_state(void) {
266:     free(g_mp4.frame.data);
267:     g_mp4.frame.data = NULL;
268:     g_mp4.frame.ents = 0;
269:     g_mp4.frame.bufsize = 0;
270:     g_mp4.framesamples = 0;
271:     g_mp4.samples = 0;
272:     g_mp4.buffersize = 0;
273:     g_mp4.mdatofs = 0;
274:     g_mp4.mdatsize = 0;
275:     memset(&g_mp4.bitrate, 0, sizeof(g_mp4.bitrate));
276: }
277: 
278: int mp4_open(const char *path, int overwrite) {
279:     mp4_close(); /* in case of a retry after a failed previous mp4_open() */
280:     reset_write_state();
281:     g_mem_error = 0;
282: 
283:     if (!overwrite && access(path, 0) == 0) return 1;
284:     g_mp4.fout = fopen(path, "wb");
285:     if (!g_mp4.fout) return 1;
286:     setvbuf(g_mp4.fout, NULL, _IOFBF, MP4_IO_BUFSIZE);
287: 
288:     g_mp4.frame.bufsize = 1024;
289:     g_mp4.frame.data = (uint32_t *)malloc(g_mp4.frame.bufsize * sizeof(uint32_t));
290:     if (!g_mp4.frame.data) return 1;
291: 
292:     g_mempos = 0;
293:     g_memcap = 1024;
294:     g_membuf = (uint8_t *)malloc(g_memcap);
295:     if (!g_membuf)
296:     {
297:         free(g_mp4.frame.data);
298:         g_mp4.frame.data = NULL;
299:         return 1;
300:     }
301: 
302:     long ftyp = start_atom("ftyp");
303:     put_data("M4A \0\0\0\0M4A mp42isom", 20);
304:     end_atom(ftyp);
305: 
306:     fwrite(g_membuf, 1, g_mempos, g_mp4.fout);
307:     free(g_membuf);
308:     g_membuf = NULL;
309: 
310:     /* mdat's size isn't known until every frame has been written, so its
311:        header goes out now as a placeholder and gets patched in mp4_finish().
312:        stco also needs mdatofs to point past this header at the first
313:        audio byte, which is why it's recorded here rather than computed later. */
314:     g_mp4.mdatofs = (uint32_t)ftell(g_mp4.fout) + 8;
315:     put_u32(0);
316:     put_data("mdat", 4);
317:     return g_mem_error ? 1 : 0;
318: }
