371: int mp4_write_frame(const uint8_t *data, uint32_t size, uint32_t samples) {
372:     if (!g_mp4.fout) return -1;
373: 
374:     if (fwrite(data, 1, size, g_mp4.fout) != size)
375:         return -1;
376:     g_mp4.mdatsize += size;
377:     g_mp4.samples += samples;
378: 
379:     /* only count frames at the established frame length toward the
380:        bitrate window, so a shorter trailing frame doesn't skew it */
381:     if (g_mp4.framesamples <= samples) {
382:         g_mp4.bitrate.size += size;
383:         g_mp4.bitrate.samples += samples;
384:         if (g_mp4.bitrate.samples >= g_mp4.samplerate) {
385:             uint32_t br = (uint32_t)((uint64_t)8 * g_mp4.bitrate.size * g_mp4.samplerate / g_mp4.bitrate.samples);
386:             if (g_mp4.bitrate.max < br)
387:                 g_mp4.bitrate.max = br;
388:             g_mp4.bitrate.size = 0;
389:             g_mp4.bitrate.samples = 0;
390:         }
391:         g_mp4.framesamples = samples;
392:     }
393: 
394:     if (g_mp4.frame.ents >= g_mp4.frame.bufsize) {
395:         uint32_t new_cap = g_mp4.frame.bufsize ? g_mp4.frame.bufsize * 2 : 1024;
396:         /* bound the frame table so an unreasonably long encode can't grow
397:            this without limit or overflow new_cap * sizeof(uint32_t) */
398:         if (new_cap > (1UL << 30)) return -1;
399:         uint32_t *tmp = (uint32_t *)realloc(g_mp4.frame.data, new_cap * sizeof(uint32_t));
400:         if (!tmp) return -1;
401:         g_mp4.frame.data = tmp;
402:         g_mp4.frame.bufsize = new_cap;
403:     }
404:     g_mp4.frame.data[g_mp4.frame.ents++] = size;
405:     if (g_mp4.buffersize < (uint16_t)size)
406:         g_mp4.buffersize = (uint16_t)size;
407:     return 0;
408: }
