498: /* Returns 0 on success, 1 on failure (mirroring mp4_open()'s convention). */
499: int mp4_finish(void) {
500:     if (!g_mp4.fout) return 1;
501:     g_mem_error = 0;
502: 
503:     /* now that all frames are written, go back and fill in the mdat
504:        size placeholder left by mp4_open() */
505:     long pos = ftell(g_mp4.fout);
506:     fseek(g_mp4.fout, g_mp4.mdatofs - 8, SEEK_SET);
507:     put_u32(g_mp4.mdatsize + 8);
508:     fseek(g_mp4.fout, pos, SEEK_SET);
509:     if (g_mem_error) return 1;
510: 
511:     g_mp4.bitrate.avg = (uint32_t)((uint64_t)8 * g_mp4.mdatsize * g_mp4.samplerate / (g_mp4.samples ? g_mp4.samples : 1));
512:     /* a file shorter than one second never crosses the sample-count
513:        threshold in mp4_write_frame, so bitrate.max would otherwise
514:        still be 0 here */
515:     if (!g_mp4.bitrate.max) g_mp4.bitrate.max = g_mp4.bitrate.avg;
516: 
517:     g_mempos = 0;
518:     g_memcap = 65536 + (size_t)g_mp4.frame.ents * 4;
519:     g_membuf = (uint8_t *)malloc(g_memcap);
520:     if (!g_membuf) return 1;
521: 
522:     long moov = start_atom("moov");
523:     long mvhd = start_atom("mvhd");
524:     uint32_t now = get_mp4_time();
525:     put_u32(0); put_u32(now); put_u32(now);
526:     put_u32(g_mp4.samplerate); put_u32(g_mp4.samples);
527:     put_u32(MP4_FP1616_ONE); put_u16(MP4_FP0808_ONE); put_u16(0); put_u32(0); put_u32(0);
528:     put_u32(MP4_FP1616_ONE); put_u32(0); put_u32(0);
529:     put_u32(0); put_u32(MP4_FP1616_ONE); put_u32(0);
530:     put_u32(0); put_u32(0); put_u32(MP4_FP0230_ONE);
531:     put_u32(0); put_u32(0); put_u32(0); put_u32(0); put_u32(0); put_u32(0);
532:     put_u32(MP4_NEXT_TRACK_ID);
533:     end_atom(mvhd);
534: 
535:     long trak = start_atom("trak");
536:     long tkhd = start_atom("tkhd");
537:     put_u32(1); put_u32(now); put_u32(now); put_u32(MP4_TRACK_ID); put_u32(0);
538:     put_u32(g_mp4.samples); put_u32(0); put_u32(0);
539:     put_u16(0); put_u16(0); put_u16(MP4_FP0808_ONE); put_u16(0);
540:     put_u32(MP4_FP1616_ONE); put_u32(0); put_u32(0);
541:     put_u32(0); put_u32(MP4_FP1616_ONE); put_u32(0);
542:     put_u32(0); put_u32(0); put_u32(MP4_FP0230_ONE);
543:     put_u32(0); put_u32(0);
544:     end_atom(tkhd);
545: 
546:     long mdia = start_atom("mdia");
547:     long mdhd = start_atom("mdhd");
548:     put_u32(0); put_u32(now); put_u32(now);
549:     put_u32(g_mp4.samplerate); put_u32(g_mp4.samples);
550:     put_u16(0); put_u16(0);
551:     end_atom(mdhd);
552: 
553:     long hdlr = start_atom("hdlr");
554:     put_u32(0); put_u32(0); put_data("soun", 4);
555:     put_u32(0); put_u32(0); put_u32(0); put_u8(0);
556:     end_atom(hdlr);
557: 
558:     long minf = start_atom("minf");
559:     long smhd = start_atom("smhd");
560:     put_u32(0); put_u16(0); put_u16(0);
561:     end_atom(smhd);
562: 
563:     long dinf = start_atom("dinf");
564:     long dref = start_atom("dref");
565:     put_u32(0); put_u32(1);
566:     long url = start_atom("url ");
567:     put_u32(MP4_URL_SELF_CONTAINED);
568:     end_atom(url);
569:     end_atom(dref);
570:     end_atom(dinf);
571: 
572:     long stbl = start_atom("stbl");
573:     long stsd = start_atom("stsd");
574:     put_u32(0); put_u32(1);
575:     long mp4a = start_atom("mp4a");
576:     put_u8(0); put_u8(0); put_u8(0); put_u8(0); put_u8(0); put_u8(0);
577:     put_u16(1); put_u32(0); put_u32(0);
578:     put_u16(g_mp4.channels); put_u16(g_mp4.bits);
579:     put_u16(0); put_u16(0); put_u16(g_mp4.samplerate); put_u16(0);
580: 
581:     long esds = start_atom("esds");
582:     put_u32(0);
583:     /* ES descriptor's declared size must cover its own fixed fields plus
584:        every nested descriptor including their headers (DecoderConfig:
585:        13 fixed + DecSpecificInfo; SLConfig: 1 fixed byte) */
586:     put_descriptor(3, 3 + MP4_DESC_HDR + 13 + MP4_DESC_HDR + g_mp4.asc.size + MP4_DESC_HDR + 1);
587:     put_u16(0); put_u8(0);
588:     put_descriptor(4, 13 + MP4_DESC_HDR + g_mp4.asc.size);
589:     put_u8(MP4_OBJECT_TYPE_AUDIO_ISO_14496_3); put_u8(MP4_STREAM_TYPE_AUDIO);
590:     put_u8((uint8_t)(MP4_DECODER_BUFFER_SIZE >> 16));
591:     put_u8((uint8_t)(MP4_DECODER_BUFFER_SIZE >> 8));
592:     put_u8((uint8_t)MP4_DECODER_BUFFER_SIZE);
593:     put_u32(g_mp4.bitrate.max); put_u32(g_mp4.bitrate.avg);
594:     put_descriptor(5, g_mp4.asc.size);
595:     put_data(g_mp4.asc.data, g_mp4.asc.size);
596:     put_descriptor(6, 1); put_u8(2);
597:     end_atom(esds);
598:     end_atom(mp4a);
599:     end_atom(stsd);
600: 
601:     long stts = start_atom("stts");
602:     put_u32(0); put_u32(1);
603:     put_u32(g_mp4.frame.ents); put_u32(g_mp4.framesamples);
604:     end_atom(stts);
605: 
606:     long stsc = start_atom("stsc");
607:     put_u32(0); put_u32(1); put_u32(1);
608:     put_u32(g_mp4.frame.ents); put_u32(1);
609:     end_atom(stsc);
610: 
611:     long stsz = start_atom("stsz");
612:     put_u32(0); put_u32(0); put_u32(g_mp4.frame.ents);
613:     if (g_mp4.frame.ents) {
614:         /* written by hand instead of looping put_u32() per entry: this
615:            table has one entry per encoded frame, so for a long file it's
616:            the hottest loop in mp4_finish() */
617:         size_t stsz_size = (size_t)g_mp4.frame.ents * 4;
618:         if (g_mempos + stsz_size > g_memcap) {
619:             size_t new_cap = g_memcap ? g_memcap * 2 : 1024;
620:             while (g_mempos + stsz_size > new_cap && new_cap < (1UL << 31)) new_cap *= 2;
621:             void *tmp = (g_mempos + stsz_size > new_cap) ? NULL : realloc(g_membuf, new_cap);
622:             if (!tmp) {
623:                 free(g_membuf);
624:                 g_membuf = NULL;
625:                 return 1;
626:             }
627:             g_membuf = (uint8_t *)tmp;
